import React, { useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faEnvelope, faLock } from '@fortawesome/free-solid-svg-icons'; 
import './Login.css';
import PageTitle from '../PageTitle';
import { useNavigate } from 'react-router-dom';

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault(); // Formun yeniden yüklenmesini engeller

    // Backend'e login isteği gönderme
    const response = await fetch('http://localhost:3001/api/login', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ email, password }),
    });

    const data = await response.json();

    if (response.ok) {
      // Giriş başarılıysa, token'ı localStorage'a kaydet
      localStorage.setItem('token', data.token);
      navigate('/admin'); // Admin sayfasına yönlendirme
    } else {
      alert(data.message); // Hata mesajını göster
    }
  };

  return (
    <>
      <PageTitle title='Giriş Yap'/>
      <div className="loginpage">
        <div className="container">
          <div className="row">
            <div className="col-sm-12">
              <div className="loginlogo">Beeonhive</div>
            </div>
          </div>
        </div>
        <div className="turnhome">
          <a href="/"><b>Ana Sayfaya Dön</b></a>
        </div>
        <div className="card">
          <div className="logincard">
            <div className="logincardbody">
              <p className="login-box-msg">Oturumunuzu başlatmak için giriş yapın</p>
            </div>
            <form onSubmit={handleLogin}>
              <div className="input-group">
                <input 
                  type="email" 
                  id="email" 
                  className="email" 
                  placeholder="E-mail" 
                  value={email}
                  onChange={(e) => setEmail(e.target.value)} 
                />
                <span className="icon-group icon-group-email">
                  <FontAwesomeIcon icon={faEnvelope} className="icon-small" />
                </span>
              </div>
              <div className="input-group">
                <input 
                  type="password" 
                  id="password" 
                  className="formcontrol" 
                  placeholder="Şifre"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)} 
                />
                <span className="icon-group icon-group-password">
                  <FontAwesomeIcon icon={faLock} className="icon-small" />
                </span>
              </div>
              <div className="row">
                <div className="col-6">
                  <button type="submit" id="btngiris" className="btngirisyap">Giriş Yap</button>
                </div>
              </div>
              <p className="sifremiunuttum">
                <a href="" target="_blank">Şifremi unuttum</a>
              </p>
            </form>
          </div>
        </div>
      </div>
    </>
  );
}

export default Login;
